    a = list(map(int, sys.stdin.readline().split()))
    result = [0] * p
    inv_denominator = pow(-1, p, p)

    for k in range(p):
        if k == 0:
            q = [0] * p
            q[0] = (-1) % p
            q[p-1] = 1 % p
        else:
            q = [0] * p
            for j in range(1, p):
                exponent = (p-1) - j
                power = pow(k, exponent, p)
                q[j] = power

        for i in range(p):
            q[i] = (q[i] * inv_denominator) % p

        for i in range(p):
            result[i] = (result[i] + q[i] * a[k]) % p

    print(' '.join(map(str, result)))

if __name__ == "__main__":
