import sys

def main():
    p = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    if p == 2:
        inv_D = 1
    else:
        inv_D = p - 1

    b = [0] * p

    for k in range(p):
        current_a = a[k]
        if current_a == 0:
            continue

        pow_k = [1] * p
        for i in range(1, p):
            pow_k[i] = (pow_k[i-1] * k) % p

        for m in range(p):
            if m == 0:
                coeff_q = (pow_k[p-1] - 1) % p
            else:
                exponent = p - 1 - m
                coeff_q = pow_k[exponent]
            contribution = (current_a * inv_D) % p * coeff_q % p
            b[m] = (b[m] + contribution) % p

    print(' '.join(map(str, b)))

if __name__ == "__main__":
    main()
