import sys

def main():
    n = int(sys.stdin.readline())
    A = list(map(int, sys.stdin.readline().split()))
    B = list(map(int, sys.stdin.readline().split()))

    if B == A:
        if n == 1:
            print("No")
            return
        perm = B.copy()
        for i in range(n):
            if perm[i] != A[i]:
                continue
            j = i + 1
            while j < n:
                if perm[j] != A[i]:
                    break
                j += 1
            if j < n:
                perm[i], perm[j] = perm[j], perm[i]
            else:
                print("No")
                return
        # Final check
